const wa = $('Extract Fields').first().json.wa_id;
const rows = $input.all().map((i) => i.json).filter((r) => r && r.id !== undefined && r.id !== null);
const live = rows.filter((r) => String(r.status || '').toLowerCase() !== 'archived');
if (live.length === 0) return [{ json: { found: false, wa_id: wa } }];
live.sort((a, b) => Number(b.id) - Number(a.id));
return [{ json: { ...live[0], found: true } }];

parameters.text:
=Lead name: {{ $json.name }}
Answers so far (JSON): {{ $json.answers || "{}" }}
