parameters.jsCode:
const ai = $input.first().json.output || {};
const lead = $('Pick Latest Lead').first().json;
const latest = String($('Extract Fields').first().json.text || '').trim();
let prev = {};
try { prev = JSON.parse(lead.answers || '{}'); } catch (e) { prev = {}; }
const incoming = (ai.answers && typeof ai.answers === 'object') ? ai.answers : {};
const clean = (v) => (v === null || v === undefined) ? '' : String(v).trim();
const norm = (v) => ' ' + clean(v).toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim() + ' ';
const has = (s, w) => s.includes(' ' + w + ' ');
const anyOf = (s, list) => list.some((w) => has(s, w));
const NUM = { one: 1, two: 2, three: 3, four: 4, five: 5, six: 6, seven: 7, eight: 8, nine: 9, ten: 10 };
const FULL = ['january','february','march','april','may','june','july','august','september','october','november','december'];

function vRentBuy(v) {
  const s = norm(v);
  if (anyOf(s, ['rent', 'renting', 'rental', 'lease', 'kiraye', 'kiray'])) return 'rent';
  if (anyOf(s, ['buy', 'buying', 'purchase', 'own', 'sale', 'invest', 'kharid', 'khareed', 'kharidna', 'kharidni'])) return 'buy';
  return null;
}
function vBudget(v, mode) {
  const s = clean(v).toLowerCase().replace(/,/g, '').replace(/aed|dhs|dirhams|dirham/g, '').replace(/ /g, '');
  const re = /([0-9]+(?:[.][0-9]+)?)(k|mn|million|thousand|m)?/g;
  const mult = (u) => (u === 'k' || u === 'thousand') ? 1000 : ((u === 'm' || u === 'mn' || u === 'million') ? 1000000 : 1);
  const parts = [];
  let m;
  while ((m = re.exec(s)) !== null && parts.length < 2) parts.push({ n: parseFloat(m[1]), u: m[2] || '' });
  if (parts.length === 0) return null;
  if (parts.length === 2 && !parts[0].u && parts[1].u) parts[0].u = parts[1].u;
  const ok = (n) => {
    if (!isFinite(n) || n < 3000 || n > 500000000) return false;
    if (mode === 'buy' && n < 100000) return false;
    if (mode !== 'buy' && n > 5000000) return false;
    return true;
  };
  const nums = parts.map((p) => Math.round(p.n * mult(p.u)));
  if (!ok(nums[0])) return null;
  if (nums.length === 2 && ok(nums[1]) && nums[1] > nums[0]) return nums[0] + '-' + nums[1];
  if (/under|below|upto|max|lessthan/.test(s)) return 'up to ' + nums[0];
  if (/\+|above|over|morethan/.test(s)) return nums[0] + '+';
  return String(nums[0]);
}
function vBedrooms(v) {
  const s = norm(v);
  if (has(s, 'studio')) return 'studio';
  const r = s.match(/([0-9]+) (?:to |or )?([0-9]+)/);
  if (r) { const a = parseInt(r[1], 10), b = parseInt(r[2], 10); if (a >= 1 && b <= 10 && b > a) return a + '-' + b; }
  const m = s.match(/[0-9]+/);
  if (m) { const n = parseInt(m[0], 10); if (n === 0) return 'studio'; return (n >= 1 && n <= 10) ? String(n) : null; }
  for (const w of Object.keys(NUM)) if (has(s, w)) return String(NUM[w]);
  return null;
}
function vArea(v) {
  const s = clean(v);
  if (s.length < 3 || s.length > 60) return null;
  const letters = /[a-z]{3,}/i.test(s) || s.split('').some((c) => c.charCodeAt(0) > 127);
  if (!letters) return null;
  if (anyOf(norm(s), ['idk', 'none', 'nothing'])) return null;
  return s;
}
function daysFrom(v) {
  const s = norm(v);
  if (s.trim() === '') return null;
  if (has(s, 'next week')) return 10;
  if (anyOf(s, ['asap', 'immediately', 'now', 'today', 'tomorrow', 'this week', 'right away', 'few days'])) return 7;
  let m = s.match(/([0-9]+) (day|days)/); if (m) return parseInt(m[1], 10);
  m = s.match(/([0-9]+) (week|weeks)/); if (m) return parseInt(m[1], 10) * 7;
  m = s.match(/([0-9]+) (month|months)/); if (m) return parseInt(m[1], 10) * 30;
  if (anyOf(s, ['next month', 'this month', 'within a month', 'a month'])) return 30;
  if (anyOf(s, ['two months', 'couple of months'])) return 60;
  if (anyOf(s, ['three months', 'quarter'])) return 90;
  if (anyOf(s, ['six months'])) return 180;
  if (anyOf(s, ['next year', 'later', 'not sure', 'unsure', 'flexible', 'dont know', 'don t know', 'no rush', 'someday'])) return 365;
  for (let i = 0; i < 12; i++) {
    if (has(s, FULL[i]) || has(s, FULL[i].slice(0, 3))) {
      const diff = (i - new Date().getMonth() + 12) % 12;
      return diff === 0 ? 15 : diff * 30;
    }
  }
  return null;
}

const FIELDS = ['rent_or_buy', 'budget_aed', 'bedrooms', 'area', 'move_in_timing'];
const L = norm(latest);
// A value is only accepted if the lead's latest message really contains it.
const support = {
  rent_or_buy: () => vRentBuy(latest) !== null,
  budget_aed: () => /[0-9]/.test(latest) || anyOf(L, ['million', 'thousand', 'k']),
  bedrooms: () => /[0-9]/.test(latest) || has(L, 'studio') || anyOf(L, Object.keys(NUM)),
  area: (v) => {
    const lv = latest.toLowerCase();
    const val = clean(v).toLowerCase();
    if (val && lv.includes(val)) return true;
    return val.split(/[^a-z0-9]+/).some((w) => w.length >= 4 && lv.includes(w));
  },
  move_in_timing: () => daysFrom(latest) !== null
};
const asked = FIELDS.find((f) => clean(prev[f]) === '') || '';

const out = {};
const rejected = [];
function pick(field, validator) {
  const inc = clean(incoming[field]);
  const old = clean(prev[field]);
  const oldOk = old ? validator(old) : null;
  if (inc && inc !== old && support[field](inc)) {
    const ok = validator(inc);
    if (ok) return ok;
    if (field === asked) rejected.push(field);
  }
  return oldOk || '';
}
out.rent_or_buy = pick('rent_or_buy', vRentBuy);
out.budget_aed = pick('budget_aed', (v) => vBudget(v, out.rent_or_buy));
const modeChanged = clean(prev.rent_or_buy) !== '' && out.rent_or_buy !== clean(prev.rent_or_buy);
if (modeChanged && out.budget_aed === clean(prev.budget_aed)) out.budget_aed = '';
out.bedrooms = pick('bedrooms', vBedrooms);
// Repair: an older version saved a range like '1-2' as '1'. Restore the range from the lead's own answer in history.
if (/^[0-9]+$/.test(out.bedrooms)) {
  const hl = clean(lead.history).split('\n');
  for (let i = 1; i < hl.length; i++) {
    if (hl[i].startsWith('Lead:') && /^Bot:.*bedroom/i.test(hl[i - 1])) {
      const r = vBedrooms(hl[i].slice(5));
      if (r && r.includes('-') && r.split('-')[0] === out.bedrooms) out.bedrooms = r;
    }
  }
}
out.area = pick('area', vArea);
out.move_in_timing = pick('move_in_timing', (v) => (daysFrom(v) === null ? null : clean(v).slice(0, 80)));

const complete = FIELDS.every((f) => out[f] !== '');
const Q = {
  rent_or_buy: 'Are you looking to rent or buy?',
  budget_aed: out.rent_or_buy === 'buy' ? 'What is your total budget in AED? (under 1M, 1M-2M, 2M-5M, 5M+)' : 'What is your yearly budget in AED? (under 50k, 50k-100k, 100k-200k, 200k+)',
  bedrooms: 'How many bedrooms do you need?',
  area: 'Which area are you interested in?',
  move_in_timing: 'When are you planning to move in?'
};

let score = '';
if (complete) {
  const d = daysFrom(out.move_in_timing);
  if (d !== null && d <= 30 && out.budget_aed) score = 'HOT';
  else if (d !== null && d <= 90) score = 'WARM';
  else score = 'COLD';
}

let first = clean(lead.name).split(' ')[0] || 'there';
first = first.charAt(0).toUpperCase() + first.slice(1);
const isFirst = clean(lead.history) === '';
// The AI only writes a short acknowledgement; the code always asks the next missing question.
const EMOJI = /[\u{1F000}-\u{1FAFF}\u{2600}-\u{27BF}\u{2300}-\u{23FF}\u{2B00}-\u{2BFF}\u{FE0F}\u{200D}]/gu;
const noEmoji = (t) => String(t || '').replace(EMOJI, '').replace(/ {2,}/g, ' ').trim();
const fmtNum = (x) => Number(x).toLocaleString('en-US');
const fmtBudget = (b) => {
  if (b.includes('-')) { const [a, c] = b.split('-'); return 'AED ' + fmtNum(a) + ' to ' + fmtNum(c); }
  if (b.startsWith('up to ')) return 'up to AED ' + fmtNum(b.slice(6));
  if (b.endsWith('+')) return 'AED ' + fmtNum(b.slice(0, -1)) + ' or more';
  return 'AED ' + fmtNum(b);
};
const CONF = {
  rent_or_buy: (v) => v === 'rent' ? 'Got it, renting!' : 'Got it, buying!',
  budget_aed: () => 'Perfect.',
  bedrooms: () => 'Nice.',
  area: () => 'Great choice!',
  move_in_timing: () => 'Sounds good.'
};
const fmtBeds = (b) => b === 'studio' ? 'a studio' : b + (b === '1' ? ' bedroom' : ' bedrooms');
const summary = 'Here is a quick summary: ' + (out.rent_or_buy === 'buy' ? 'buying' : 'renting') + ', ' + (out.budget_aed ? fmtBudget(out.budget_aed) + (out.rent_or_buy === 'buy' ? ' total' : ' a year') : '') + ', ' + fmtBeds(out.bedrooms) + ', ' + out.area + ', moving in ' + out.move_in_timing + '.';
const newField = FIELDS.find((f) => out[f] !== '' && out[f] !== clean(prev[f]));
let ack = noEmoji(clean(ai.reply).replace(/\s+/g, ' '));
if (!ack || ack.length > 220 || ack.includes('?') || /https?:|www[.]/i.test(ack) || /[0-9]{9,}/.test(ack) || /noted|recorded|confirm/i.test(ack) || ack.split(' ').length > 8) ack = '';
if (!ack && newField) ack = CONF[newField](out[newField]);
if (!ack && isFirst) ack = 'Hi ' + first + '! I am your Dubai property assistant.';
const nextField = FIELDS.find((f) => out[f] === '');
let reply;
if (complete) reply = 'Thanks ' + first + '! ' + summary;
else if (rejected.length > 0) reply = 'Sorry, I did not quite catch that. ' + Q[rejected[0]];
else reply = (ack ? ack + ' ' : '') + Q[nextField];
reply = noEmoji(reply);

const clip = (s, n) => clean(s).replace(/\s+/g, ' ').slice(0, n);
const lines = clean(lead.history) ? clean(lead.history).split('\n') : [];
if (latest) lines.push('Lead: ' + clip(latest, 200));
lines.push('Bot: ' + clip(reply, 250));
const history = lines.slice(-10).join('\n');

return [{ json: { output: { reply, answers: out, complete, score, rejected, history } } }];

